// Turns the timezone chosen in Settings into the values the rest of the flow needs,
// so the 24h window follows the owner's locale instead of the n8n instance timezone.
const cfg = $('Settings').first().json;
const tz = cfg.timezone || 'UTC';

const now = DateTime.now().setZone(tz);
const windowStart = now.minus({ hours: 24 });

return [{
  json: {
    timezone: tz,
    todayLabel: now.toFormat('cccc d LLLL yyyy'),
    windowStartIso: windowStart.toUTC().toISO(),
    sinceDate: windowStart.toFormat('yyyy-LL-dd'),
  },
}];

// One item per account so the HTTP node can throttle a request per handle.
// Accepts handles with or without the leading @.
const accounts = $('Settings').first().json.x_accounts || [];

return accounts
  .map((a) => String(a).trim().replace(/^@/, ''))
  .filter((a) => a !== '')
  .map((username) => ({ json: { username } }));

// Processes the TwitterAPI.io advanced_search response.
// The HTTP node returns one item per account, each shaped { tweets: [...], has_next_page, next_cursor }.
const win = $('Compute 24h window').first().json;
const cutoff = DateTime.fromISO(win.windowStartIso, { setZone: true });

const out = [];

for (const item of $input.all()) {
  const body = item.json || {};
  const tweets = Array.isArray(body.tweets) ? body.tweets : [];

  for (const tw of tweets) {
    if (!tw || !tw.id || !tw.text) continue;

    // Drop replies and retweets: a digest should only carry original posts
    if (tw.isReply === true) continue;
    if (tw.retweeted_tweet) continue;

    // Precise 24h filter. createdAt arrives as "Tue Dec 10 07:00:30 +1234567890"
    if (tw.createdAt) {
      const created = DateTime.fromFormat(tw.createdAt, 'ccc LLL d HH:mm:ss ZZZ yyyy', { setZone: true });
      if (created.isValid && created < cutoff) continue;
    }

    const account = tw.author && tw.author.userName ? tw.author.userName : null;

    out.push({
      json: {
        tweetId: String(tw.id),
        account: account ? ('@' + account) : '@unknown',
        text: String(tw.text).trim(),
        url: tw.url || (account ? ('https://x.com/' + account + '/status/' + tw.id) : ('https://x.com/i/status/' + tw.id)),
        createdAt: tw.createdAt || null,
        likeCount: tw.likeCount ?? null,
        retweetCount: tw.retweetCount ?? null,
      },
    });
  }
}

// Emit a marker rather than nothing, so the downstream nodes still receive an item.
if (out.length === 0) {
  return [{ json: { marker: 'no_tweets' } }];
}

return out;

const win = $('Compute 24h window').first().json;
const cfg = $('Settings').first().json;
const tweets = $('Normalize tweets').all().map((i) => i.json).filter((t) => t.tweetId);

// 'Log account skip' only runs when at least one account failed. When every account
// succeeds that node never executes and referencing it throws, so the read is guarded.
let skipped = [];
try {
  skipped = $('Log account skip').all().map((i) => i.json).filter((s) => s.skipped);
} catch (e) {
  skipped = [];
}

const seen = new Set();
const unique = [];
for (const t of tweets) {
  if (seen.has(t.tweetId)) continue;
  seen.add(t.tweetId);
  unique.push(t);
}

unique.sort((a, b) => String(a.createdAt || '').localeCompare(String(b.createdAt || '')));

return [{
  json: {
    date: win.todayLabel,
    chatId: cfg.telegram_chat_id,
    tweetCount: unique.length,
    tweetsJson: JSON.stringify(unique, null, 2),
    skippedAccounts: skipped.map((s) => s.account),
    skippedCount: skipped.length,
  },
}];

