const cfg = $('Build digest input').first().json;
const raw = $('Curate daily digest').first().json;
const body = String(raw.output || raw.text || '').trim();

return [{
  json: {
    chatId: cfg.chatId,
    text: body || '☕ Daily Tech Digest\n\nThe digest could not be generated today.',
  },
}];

const cfg = $('Build digest input').first().json;

let text = '☕ *Daily Tech Digest* — ' + cfg.date +
  '\n\nNo original posts worth reporting in the last 24 hours from the monitored accounts.';

if (cfg.skippedCount > 0) {
  text += '\n\n⚠️ Accounts that could not be read (' + cfg.skippedCount + '): ' + cfg.skippedAccounts.join(', ');
}

return [{ json: { chatId: cfg.chatId, text } }];

// Only runs when an account's request failed. n8n keeps the failing item's original
// fields next to the error payload, so the username is usually still readable.
return $input.all().map((item) => {
  const j = item.json || {};
  const username = j.username || '';
  return {
    json: {
      skipped: true,
      account: username ? '@' + username : 'unknown account',
      reason: j.error?.message || j.error || 'request failed',
    },
  };
});
